    ('admin.article.edit.changePathHint', 'en-US', 'Changing the URL leaves the article content alone: body, SEO fields and template bindings all stay as they are; the artifact is simply rebuilt at the new path and the old link is handled as chosen above.', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
