    ('admin.article.edit.importCopyTail', 'zh-CN', '而不是绑定：之后改文章不会改页面，改页面也不会改文章 —— 两边各有各的真源，互不影响。', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
    ('admin.article.edit.importCopyTail', 'en-US', ' rather than a binding: later edits to the article do not change the page, and edits to the page do not change the article — each side keeps its own source of truth.', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
