    ('admin.article.edit.importPreviewTail', 'zh-CN', '的正文（预览与创建必须基于同一份内容，否则「预览没问题的」和「创建出来的」会不一样）：改完正文先保存，再预览。', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
    ('admin.article.edit.importPreviewTail', 'en-US', ' body (the preview and the creation must work from the same content, otherwise "the preview looked fine" and "what was created" will differ): save the body first, then preview.', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
