    ('admin.article.edit.importWhitelistMid', 'zh-CN', '正文保存时会过一遍富文本白名单（段落、标题、列表、引用、代码块、链接、图片），', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
    ('admin.article.edit.importWhitelistMid', 'en-US', 'A rich-text allowlist (paragraphs, headings, lists, quotes, code blocks, links, images) runs over the body when it is saved, ', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
    ('admin.article.edit.importWhitelistStrong', 'zh-CN', '分隔线与表格不在白名单里', 200, 'admin', 'admin/article_edit.html', 1, now(), now()),
